package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamSabaragamuwaFolkBank2 {
    private const val T = "සබරගමු නර්තන සම්ප්‍රදාය හා ජන නැටුම්"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("සබරගමු නැටුමේදී 'මට්ටි සරඹ' අභ්‍යාස මාලාව අවසන් කළ පසු ශිෂ්‍යයාට ඉගැන්වෙන මීළඟ අංගය කුමක්ද?", "තේරුම් පද, වට්ටම් පද සහ සබරගමු වන්නම්", "පහතරට සන්නි මුහුණු කැපීම", "උඩරට කස ගැසීම", "බටහිර ටැප් ඩාන්ස්", "මූලික සරඹවලින් පසු ප්‍රාසාංගික සබරගමු නැටුම් අංග වෙත යොමු කෙරේ."),
        q("සබරගමු දිගු දවුලේ වම් ඇස හා දකුණු ඇස සඳහා භාවිත කරන සම් වර්ග මොනවාද?", "වම් ඇසට ගව සම හා දකුණු ඇසට එළු හෝ ගව සම", "දෙපසටම ප්ලාස්ටික් පටල", "වීදුරු තහඩු", "ලී පියන්", "කඩිප්පුවෙන් ගසන පැත්ත හා අතින් ගසන පැත්ත අනුව සම් තද බව වෙනස් වේ."),
        q("සබරගමු නර්තනයේ 'ගමන් පද' ඉදිරිපත් කිරීමේදී නැට්ටුවාගේ ඉණ හා කඳ ක්‍රියා කළ යුතු ආකාරය කුමක්ද?", "සෞම්‍ය ලෙස තාලයට පැද්දෙමින් හා කරකැවෙමින්", "ගල් ගැසුණු ලී කඳක් මෙන් තදින්", "ඉදිරියට වැටෙමින්", "දණ ගසාගෙන", "සබරගමු ලාලිත්‍යය රැඳී ඇත්තේ උඩුකයේ මෘදු පැද්දීම මතය."),
        q("රත්නපුර මහ සමන් දේවාලයේ ඇසළ පෙරහැරේදී සබරගමු නැටුම්වලට හිමි වන විශේෂ ස්ථානය කුමක්ද?", "සමන් දෙවි ආභරණ හා කුඹල් පෙරහැර ඉදිරියේ ගෞරවයෙන් නැටීම", "පෙරහැර අවසානයේ නැටුම් නොපැවැත්වීම", "විදේශීය ගීත වාදනය කිරීම", "හිඳගෙන නැටීම", "මහ සමන් දේවාල පෙරහැර සබරගමු කලා උරුමයේ මහඟු සංදර්ශනයයි."),
        q("සබරගමු සම්ප්‍රදායේ 'වෙස් ඇඳුම' හා සමානව භාවිත කරන නර්තන ඇඳුම් කට්ටලය හඳුන්වන්නේ කෙසේද?", "පායිම්පත් හා හැට්ට සමඟ රැළි හඟල ඇඳුම", "උඩරට වෙස් තට්ටු කට්ටලය", "සොකරි කමත් ඇඳුම", "භරත නාට්‍යම් කාන්තා ඇඳුම", "සුදු ජටාව හා උඩුකය හැට්ටය සබරගමු ඇඳුමේ පැහැදිලි ලක්ෂණ වේ."),
        q("ජන නැටුම් අතර 'පන්දම් නැටුම' හෝ 'ගිනි සිසිල' පැවැත්වීමේදී නැට්ටුවන් විශේෂයෙන්ම ආරක්ෂා කළ යුතු කරුණ කුමක්ද?", "ආරක්ෂිත දුර පවත්වා ගනිමින් දැල්ල පාලනය කිරීම", "වියළි තණකොළ මත පන්දම් දැමීම", "දෑස් පියාගෙන පන්දම් විසි කිරීම", "නරඹන්නන් අතරට දුව යාම", "ගින්න සමඟ කරන නර්තනයේදී ඉහළ ශාරීරික පාලනයක් හා පුහුණුවක් තිබිය යුතුය."),
        q("සිංහල ගැමි නැටුමක් වන 'ලී කෙළි නැටුම' බහුලව ඉදිරිපත් කරන කණ්ඩායම් සංඛ්‍යාව කෙබඳු වේද?", "යුගල වශයෙන් සිටින සමතුලිත පිරිසක් (උදා 8, 12 හෝ 16)", "එක් තනි පුද්ගලයෙක් පමණි", "දෙදෙනෙකු පමණක් බිම වාඩි වී", "සිය ගණනක් පොදි ගැසී", "ඉරට්ටේ සංඛ්‍යාවක් සිටීම නිසා යුගල හා කවුන්ටර පහරවල් පහසුවෙන් සිදු කළ හැකිය."),
        q("ගොයම් නැටුමේදී 'ගොයම් කවි' ගායනා කිරීමෙන් ගැමි කාන්තාවන් ලැබූ ප්‍රධාන මානසික ප්‍රතිලාභය කුමක්ද?", "ගොවිබිමේ වෙහෙස මහන්සිය අමතක වී සතුටින් වැඩ කිරීමට හැකි වීම", "ගොවිබිමේ වැඩ කටයුතු අතපසු වී අස්වැන්න අඩු වීම", "ගැමි කාන්තාවන් අතර එකිනෙකා සමඟ අමනාපකම් ඇති වීම", "තාලය නොමැතිව වැඩ කිරීමෙන් ඉක්මනින් නිදිමත ඇති වීම", "ජන ගී හා නැටුම් ශ්‍රමයේ වෙහෙස නිවා දමන කලා මාධ්‍යයකි."),
        q("කළගෙඩි නැටුමේදී නැට්ටුවන් විසින් කළගෙඩිය කරකැවීමේදී එය බිම නොවැටී රඳවා ගැනීමට භාවිත කරන ශිල්පීය ක්‍රමය කුමක්ද?", "අත්ල හා ඇඟිලිවල මෘදු සමබරතාව හා කළ ගෙඩියේ කේන්ද්‍රය හඳුනාගැනීම", "කළගෙඩිය අතේ ඇඟිලිවලින් තදින් අල්ලා ඇලවෙන සේ තබා ගැනීම", "කළගෙඩියේ කර වටා රෙදි නූලක් ගැටගසා කරේ එල්ලා ගැනීම", "කළගෙඩියේ බර වැඩි කිරීමට ඇතුළත වැලි හා ගල් දමා පිරවීම", "නිවැරදි මැණික් කටු චලනයෙන් කළගෙඩිය හිස, ඉණ හා අත මත රඳවා ගනී."),
        q("සබරගමු නර්තන කලාවේ 'මණ්ඩි සරඹ' පුහුණු කිරීමේදී නැට්ටුවා 'බිම ස්පර්ශ කරන' ඉරියව්ව කුමක්ද?", "දෙපා පළල්ව නවා වම් හා දකුණු පාද සමබරව තැබීම", "වැලමිටෙන් ඇවිදීම", "හිස බිම ගැසීම", "දණහිස් බිම දිගේ ඇදීම", "පහළ සිරුරේ සමතුලිත බව හා ශක්තිය මට්ටි සරඹවලින් වර්ධනය වේ."),
        q("සබරගමු නැටුමේදී 'හොරණෑව' වාදනය කිරීමෙන් ලැබෙන ප්‍රධාන සෞන්දර්ය දායකත්වය කුමක්ද?", "දවුල් හා තම්මැට්ටම් නාදයට ඉහළින් මිහිරි තනුවක් හා නාද මාධූර්යයක් එක් කිරීම", "සමස්ත දවුල් හා තම්මැට්ටම් බෙර හඬ මුළුමනින්ම වසා දැමීම සිදු කිරීම", "පූජා අවස්ථාවේදී නැට්ටුවන්ගේ පාද චලන සම්පූර්ණයෙන්ම නැවැත්වීම", "තාලම්පට වාදනය මඩුවෙන් සම්පූර්ණයෙන් ඉවත් කර නිහඬතාව ඇති කිරීම", "හොරණෑවේ තියුණු මියුරු නාදය ශාන්තිකර්ම හා පෙරහැර වාතාවරණය වර්ණවත් කරයි."),
        q("සබරගමු සම්ප්‍රදායේ 'පහන් මඩුවකදී' පත්තිනි දේවියගේ කතා පුවත හා බැඳුණු කවි හැඳින්වෙන්නේ කෙසේද?", "පන්තිස් කෝල්මුර කවි හෝ පත්තිනි කවි", "වන්නම් කවි", "කෝලම් කවි", "රබන් කවි", "පත්තිනි මෑණියන්ගේ අනුභාවය වර්ණනා කරන පන්තිස් කෝල්මුර කවි පහන් මඩුවේ ගැයේ."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ 'වඩිග පටුන' වැනි අංග වෙනුවට ඇති ප්‍රධාන පූජා නාට්‍ය අංගය කුමක්ද?", "අඹ විදමන හා මල් යහන් නැටුම්", "දහඅට සන්නිය", "සොකරි කෝලම", "තුරඟා වන්නම", "පත්තිනි උපත හා බැඳුණු අඹ විදමන පහන් මඩුවේ ඉතා ආකර්ෂණීය අංගයකි."),
        q("ජන නැටුම් අතර 'පොල් කටු නැටුම' ඉදිරිපත් කරන ශිල්පීන් තාල ගැසීම සඳහා පොල් කටු ගටන ක්‍රම මොනවාද?", "ශරීරය ඉදිරිපස, හිසට ඉහළින්, දණහිස් අසලින් හා සහකරුගේ පොල් කටුවල", "මඩු බිමේ වැලි යට පොල් කටු වළලා පාදවලින් පෑගීම", "වතුර පිරවූ කළගෙඩි තුළ පොල් කටු ඔබා හඬ නැංවීම", "දිගු දවුලේ හම් මත පොල් කටු තබා තාලයට පහර දීම", "විවිධ මට්ටම්වලදී පොල් කටු ගැසීමෙන් ප්‍රේක්ෂකයන් තුළ විචිත්‍ර රිද්ම හැඟීමක් ඇති වේ."),
        q("සබරගමු නැටුමේදී 'තාලම්පට' වාදනය කරන ශිල්පියා විසින් අනුගමනය කරනු ලබන තාල රටාව කුමක්ද?", "සබරගමු දිගු දවුලේ ලය හා මාත්‍රා රටාවට අනුව ස්ථිර නාද දීම", "නැට්ටුවා නොසලකා හිතුමතේ වේගය වැඩි කරමින් වැයීම", "නැටුම මැද තාලම්පට බිම තබා අත්පුඩි පමණක් ගැසීම", "දේශීය ලය වෙනුවට බටහිර මාර්ච් තාල රටා ඇල්ලීම", "නැට්ටුවන් සමූහයම එකම ලයක තබා ගැනීමට තාලම්පට උදව් වේ."),
        q("සබරගමු සම්ප්‍රදායේ 'ගරා යකුම' පැවැත්වීමේදී ගරා යකා පළඳින වෙස්මුහුණෙහි ඇති සුවිශේෂී අංගය කුමක්ද?", "හිස මත හා දෙපස නාග පෙන හා රන් පැහැ සැරසිලි", "සම්පූර්ණ කළු පැහැති සමතල ලෑල්ලක්", "මල් වට්ටියක්", "පිදුරු තොප්පියක්", "සියලු යාග දෝෂ සමනය කර සෞභාග්‍යය ගෙනෙන දේව ගණයට ගරා යකා අයත් වේ."),
        q("සිංහල ගැමි නැටුමක් වන 'කුලු නැටුමේදී' කුලු කරකැවීම හා පෙළීමේ චලන මගින් පිළිබිඹු වන්නේ කුමක්ද?", "ගැමි කාන්තාවගේ කඩිසර ගෘහස්ථ ශ්‍රමය හා කලාත්මක රිද්මය", "රාජ සභාවේ පැවති නාඩගම් නීති හා සභා චාරිත්‍ර", "පහතරට සන්නි යකුන්ගේ පිදේනි තටු සැකසීමේ පිළිවෙත", "මුහුදුබඩ ධීවර කාර්මිකයන්ගේ දැල් ඇදීමේ වෙහෙස", "ගැමි කාන්තාවගේ එදිනෙදා වී පෙළීම කුලු නැටුමෙන් උසස් කලාවක් බවට පත් වී ඇත."),
        q("සබරගමු නර්තනයේ 'කලස් නැටුම' සඳහා යොදාගන්නා කලස සැරසීමට ගන්නා සාම්ප්‍රදායික ද්‍රව්‍ය මොනවාද?", "පොල් මලක්, බුලත් කොළ සහ සුදු හෝ රතු රෙදි", "ප්ලාස්ටික් සැරසිලි", "යකඩ කම්බි", "රබර් පටි", "ශුභ මංගල වස්තුවක් වන පුන්කලස පොල් මලින් සරසා භාවිත කෙරේ."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ 'දිගු දවුල' නිපදවීමේදී දෙපස සම් ඇද තබා ගැනීමට භාවිත කරන ලණු පද්ධතිය කුමක්ද?", "වරපටි හෙවත් මදු ලණු", "යකඩ දම්වැල්", "නයිලෝන් පටි පමණි", "රබර් ටියුබ්", "හම්වලින්ම කපා ගත් ශක්තිමත් වරපටිවලින් සම් තද කර තබයි."),
        q("සබරගමු නර්තන ශිල්පියෙකු පුහුණු වන 'තෙල්මේ' නොවන සබරගමුවට ආවේණික වන්නමක් කුමක්ද?", "සැවුලා වන්නම හෝ බඹර වන්නම", "දහඅට සන්නි වන්නම", "කපිරිඤ්ඤා වන්නම", "ජසයා වන්නම", "සබරගමු සම්ප්‍රදායේ ආවේණික කවි හා පද ඇසුරෙන් සබරගමු වන්නම් නිර්මාණය වී ඇත."),
        q("ජන නැටුම් අතරින් 'අත් රබන්' නැටුමේදී නැට්ටුවන් රබාන අතින් හසුරුවන ආකාරය කුමක්ද?", "එක් අතක ඇඟිල්ලකින් හෝ අල්ලෙන් රබාන කරකවමින් අනෙක් අතින් තට්ටු කිරීම", "රබාන වේදිකාවේ බිම තබා දෙපයින් ගසමින් රිද්ම මැවීම", "රබාන දිය කළයක ඔබා ශබ්දය වෙනස් කර වාදනය කිරීම", "දෙදෙනෙකු බංකුවක හිඳ බංකු රබාන මෙන් එය වැයීම", "රබන් කරකැවීම සහ විසි කර අල්ලා ගැනීම මෙම නැටුමේ විචිත්‍ර අංගයන්ය."),
        q("සබරගමු නැටුමේදී 'මණ්ඩිය' තැබීමේදී නැට්ටුවාගේ 'හිස හා බෙල්ල' චලනය විය යුත්තේ කෙසේද?", "වක්‍ර ලාලිත්‍යයෙන් යුක්තව අත් චලන අනුගමනය කරමින්", "ඉතා තදින් කෙළින් ගල් ගැසී", "පිටුපසට කඩා වැටෙමින්", "දෑස් වසාගෙන", "සබරගමු නැටුමේ සියුම් නම්‍යශීලී ගුණය හිස හා උරහිස් චලනවලින් මතු වේ."),
        q("සබරගමු 'පහන් මඩුව' ශාන්තිකර්මයේදී ආරක්ෂක පහන් පැල හෙවත් මල් යහන් සාදන්නේ කුමන ද්‍රව්‍යවලින්ද?", "ගොක් කොළ, කෙසෙල් කඳන් සහ පුවක් ලී", "සිමෙන්ති සහ ගඩොල්", "යකඩ පයිප්ප", "ප්ලාස්ටික් පුවරු", "පරිසර හිතකාමී හා පිරිසිදු ස්වාභාවික ශාක කොටස් යොදා තොරණ හා යහන් බඳියි."),
        q("සබරගමු සම්ප්‍රදායේදී 'පහිම්පත් මංගල්‍යය' පැවැත්වීමේදී ශිෂ්‍යයාට ලැබෙන වගකීම කුමක්ද?", "පරම්පරාගත සබරගමු නර්තන කලාව නිවැරදිව රැකගෙන ඉදිරියට ගෙන යාම", "නැටුමෙන් සම්පූර්ණයෙන් ඉවත් වීම", "වෙනත් සම්ප්‍රදායන් විවේචනය කිරීම", "දවුල් වාදනය නතර කිරීම", "කලාවේ ගෞරවය හා ශාස්ත්‍රීය අනන්‍යතාව රැකීම සෑම ශිල්පියෙකුගේම යුතුකම වේ."),
        q("ගැමි ජන නැටුමක් වන 'මල් නැටුම' ඉදිරිපත් කරන විට ශිල්පිනියන්ගේ ඇඳුම කෙබඳු විය යුතුද?", "චාම්, පිරිසිදු හා පාරම්පරික රෙදි හැට්ට හෝ ළමා සාරි", "රෞද්‍ර රකුසු මුහුණු හා කඩු", "තද කළු කබා", "සපත්තු හා තොප්පි", "පූජනීය හා සෞම්‍ය ගුණය ඉස්මතු වන ලෙස සරල දේශීය ඇඳුම් භාවිත කෙරේ."),
        q("සබරගමු නැටුමේ 'පද කොටස්' හා 'උඩරට නැටුමේ පද' සංසන්දනය කිරීමේදී පෙනෙන ප්‍රධාන වෙනස කුමක්ද?", "සබරගමු පද දිගු දවුලේ හඬ හා ලැසි චලනවලට අනුව දිගැති සෞම්‍ය රටාවක් ගැනීම", "සබරගමු නැටුමේ කිසිදු නිශ්චිත තාල රටාවක් නොමැති වීම", "උඩරට වෙස් නැටුමේදී දිගු දවුල පමණක් ප්‍රධාන බෙරය වීම", "සබරගමු නැටුමේදී කවි හා සීපද ගායනා සම්පූර්ණයෙන් නොතිබීම", "ප්‍රාදේශීය බෙරයේ හඬ අනුව නර්තන පද මාලා හැඩගැසී ඇත."),
        q("සබරගමු සම්ප්‍රදායේ 'වන්නම්' හා 'තේරුම් පද' වලදී ශිල්පියා පෙන්නුම් කරන 'අභිනය' කුමක්ද?", "කවියේ අදහස සුමට හස්ත මුද්‍රා හා මුහුණු භාවයන්ගෙන් දැක්වීම", "හඬ නඟා හිනැහීම", "ප්‍රේක්ෂකයන්ට පිටුපා සිටීම", "වේදිකාවෙන් ඉවත් වීම", "වචනයට අනුව භාවය ප්‍රකාශ කිරීම සබරගමු නැටුමේද අනිවාර්ය අංගයකි."),
        q("ශ්‍රී ලංකාවේ ජන නැටුම් අතර 'පන්දම් පාලිය' සහ 'ගිනි පෑගීම' වැඩි වශයෙන් සම්බන්ධ වන්නේ කුමන ඇදහිල්ලකටද?", "පත්තිනි සහ දෙවොල් දේව ඇදහිල්ලට", "ගැමි කෘෂිකාර්මික ගොයම් කැපීමට", "ලී කෙළි හා පොල්කෙළි ජන ක්‍රීඩාවලට", "සිංහල අලුත් අවුරුදු රබන් තරගවලට", "දෙවියන්ගේ බලයෙන් ගින්න පාලනය කළ හැකි බව විශ්වාස කරමින් මේවා පවත්වයි."),
        q("සබරගමු නැටුමේදී 'තම්මැට්ටම' වැඩි වශයෙන්ම වාදනය කරනු ලබන්නේ කුමන බෙරය සමඟ එක්වද?", "දිගු දවුල සමඟ", "තබ්ලාව සමඟ", "අත් රබාන සමඟ", "ගිටාරය සමඟ", "දවුල සහ තම්මැට්ටම එක්ව ගැඹුරු හා තියුණු නාද සංකලනයක් මවයි."),
        q("සබරගමු නර්තන ක්ෂේත්‍රයේදී 'පහන් මඩු' ශාන්තිකර්මය සඳහා සාමාන්‍යයෙන් ගත වන කාලය කෙබඳුද?", "සන්ධ්‍යාවේ සිට පසුදා උදෑසන දක්වා එක් රැයක් පුරා", "විනාඩි දහයක් පමණි", "සති හතරක් එක දිගට", "දහවල් පැය භාගයක් පමණි", "සියලු චාරිත්‍ර හා පූජා අනුපිළිවෙළින් එළිවෙන තුරු පවත්වනු ලැබේ."),
        q("ජන නැටුම් පුහුණු වන පාසල් සිසුන් 'සමූහ නැටුම් රටා' වෙනස් කරන විට අවධානය යොමු කළ යුත්තේ කුමකටද?", "තාල ගණනට අනුව එක්ව ස්ථාන මාරු වී රටාවේ සමමිතිය රැකගැනීමට", "තාලය නොසලකා හිතුමතේ වේදිකාව හරහා දිව යාමට", "සගයන්ගේ ගමන් මඟ අවහිර කරමින් රටාව බිඳ දැමීමට", "නැටුම අතරමග නවතා ප්‍රේක්ෂකයන් සමඟ කතා කිරීමට", "සංවිධානාත්මක ස්ථාන මාරුවීම් නර්තනයේ වෘත්තීය නිමාව පෙන්වයි."),
        q("සබරගමු නැටුමේ 'පහළ රැළි ඇඳුම' ඇඳීමේදී වළලුකර දක්වා දිගට නොව දණහිසින් මඳක් පහළට අඳින්නේ ඇයි?", "පාද චලන හා මණ්ඩි ඉරියව් පැහැදිලිව පෙනීමට හා පැටලී වැටීම වැළැක්වීමට", "සාම්ප්‍රදායික ඇඳුම් සඳහා රෙදි ප්‍රමාණය අඩු නිසා", "පාදවල පැළඳි බටහිර සපත්තු ප්‍රේක්ෂකයන්ට පෙන්වීමට", "වේදිකාව මත නටන විට රෙද්දේ බර අඩු කර ගැනීමට පමණි", "වේගවත් පාද චලනවලදී රෙද්ද බාධාවක් නොවීමට එසේ අඳිනු ලැබේ."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ 'වෙස් ඇඳුමට' වෙනස්ව කාන්තා නැටුම් සඳහා යොදාගන්නා ප්‍රධාන ඇඳුම කුමක්ද?", "සබරගමු කාන්තා ලැසි ඇඳුම හෙවත් හැට්ටය සහ රැළි ඔසරිය", "පිරිමි වෙස් තට්ටුව", "කෝලම් ලී මුහුණ", "බටහිර කලිසම්", "කාන්තාවන් සඳහා ශෛලියට ගැළපෙන සංවර හා අලංකාර ඇඳුමක් සකසා ඇත."),
        q("සිංහල ජන නැටුම් අතර 'පන්තේරු' නොවන එහෙත් තාලය සඳහා වටකුරු උපකරණයක් අතින් ගන්නා නැටුම කුමක්ද?", "අත් රබන් නැටුම", "ගොයම් නැටුම", "ලී කෙළි නැටුම", "කළගෙඩි නැටුම", "වටකුරු රාමුවක සම් ගැසූ අත් රබාන ජන නැටුම්වල බහුලව භාවිත වේ."),
        q("සබරගමු නැටුමේදී 'දවුල් පද' වාදනය කරන විට වම් අත සහ දකුණු අත කරන කාර්යයන් මොනවාද?", "වම් අතින් තද කළ හා විවෘත නාදද, දකුණු අතේ කඩිප්පුවෙන් තියුණු පහරද දේ", "දෙඅතින්ම පහර නොදී දවුල කරේ එල්ලාගෙන සිටීම", "වම් අතින් බෙරය ඔසවාගෙන දකුණු අත ඉණේ තබා ගැනීම", "දෙඅතේම කඩිප්පු දෙකක් රඳවා එකවර ගැසීම පමණි", "අත හා කඩිප්පුව එක්වීමෙන් දිගු දවුලේ අනන්‍ය නාදය උපදී."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ ඉතිහාසය හැදෑරීමේදී හමුවන ප්‍රධාන ශාන්තිකර්ම යුගලය කුමක්ද?", "පහන් මඩුව සහ මඩු ශාන්තිකර්මය", "දහඅට සන්නිය සහ සූනියම් කැපිල්ල", "සොකරි සහ කෝලම්", "කථකලි සහ භරත", "සබරගමු පළාතේ ග්‍රාමීය දේව පූජා මෙම මඩු ශාන්තිකර්ම ලෙස පවතී."),
        q("ජන නැටුම් අතර 'පොල් අඩව්ව' හෝ 'පොල් නැටුම' ඉදිරිපත් කිරීමේදී ශිල්පීන් තුළ තිබිය යුතු මූලික කුසලතාව කුමක්ද?", "වේගවත් රිද්මයකට පොල් කටු ගටමින් මණ්ඩි සමබරතාව රැකගැනීම", "හිස මත බර මැටි කළගෙඩි දෙකක් සමබරව තබා ගැනීම", "දෑස් පියාගෙන තාලම්පට නාදය අනුකරණය කර ගැයීම", "වේදිකාව මත හිඳගෙන කවි පොත් බලාගෙන ගායනා කිරීම", "වේගවත් පාද මාරුව හා පොල් කටු හඬ එකට බැඳිය යුතුය."),
        q("සබරගමු නර්තන ක්ෂේත්‍රයේ 'ගුරුකුල' රැකගැනීම සඳහා වත්මන් පාසල් හා කලායතන ඉටු කරන මෙහෙය කුමක්ද?", "විධිමත් විෂය නිර්දේශ ඔස්සේ සබරගමු සරඹ හා පද ඉගැන්වීම", "සබරගමු නැටුම් තහනම් කිරීම", "දිගු දවුල් වෙනුවට ගිටාර් දීම", "කවි පොත් විනාශ කිරීම", "පරම්පරාගත ශිල්පය සියලු සිසුන්ට පොදුවේ ලබා දීමට විෂය මාලාව උපකාරී වේ."),
        q("සබරගමු නැටුමේදී 'සුමන සමන් දෙවියන්' වර්ණනා කරමින් නටන නැටුම් කවිවලින් පෙන්වන්නේ කුමක්ද?", "සමනොළ කන්ද, ශ්‍රී පාදය හා සමන් දෙවි ගුණ", "විදේශීය නාට්‍ය හා කාව්‍ය වර්ණනා", "කෝලම් රජ සභා නඩු තීන්දු විස්තර", "භරත නාට්‍යම් හස්ත මුද්‍රා නාමාවලි", "ප්‍රදේශයේ පාරිසරික හා ආගමික ගෞරවය සබරගමු කවිවලින් මතු වේ."),
        q("ජන නැටුම් අංගයක් වන 'සවරම් නැටුමේදී' සවරම් යුගලය අතින් ගෙන නටන විට අවධානය යොමු කරන්නේ කුමකටද?", "සවරම් දෙක එකම වේගයකින් හා රටාවකින් කරකැවීමට", "සවරම් බිම අතහැරීමට", "එක් අතක් පමණක් සෙලවීමට", "නැටුම අතරමග හිඳගැනීමට", "සමමිතික සවරම් චලන නැටුමට ආකර්ෂණීය බවක් එක් කරයි."),
        q("සබරගමු සම්ප්‍රදායේ 'මට්ටි සරඹ' පුහුණුවීමේදී ආධුනිකයා 'තාල ශාස්ත්‍රය' ගැන අවබෝධ කර ගන්නේ කුමක්ද?", "මන්ද, මධ්‍ය හා ද්‍රුත ලයට පියවර තබන ආකාරය", "පින්තාරු වර්ණ මිශ්‍ර කිරීම", "වෙස්මුහුණු කැපීම", "මැටි කළ සෑදීම", "ලය තුනෙහි පාලනය මට්ටි සරඹවලින් ප්‍රායෝගිකව උගනී."),
        q("සබරගමු නර්තනයේදී 'තීර්මාන' පදයකින් සිදු කරන ප්‍රධාන කාර්යය කුමක්ද?", "එක් නැටුම් පද කොටසක් හෝ වට්ටමක් අලංකාර ලෙස අවසන් කිරීම", "නැටුමේ ආරම්භයට පෙර නිදා ගැනීම", "බෙරය මාරු කිරීම", "වේදිකාවෙන් පිටව යාම", "නැටුම් ඛණ්ඩයක නිමාව සලකුණු කිරීමට තීර්මානය යොදා ගනී."),
        q("ගැමි ජන නැටුමක් වන 'කළගෙඩි නැටුම' ඉදිරිපත් කරන විට එම නැටුමට වඩාත්ම ගැළපෙන වාද්‍ය භාණ්ඩය කුමක්ද?", "දවුල, ගැටබෙරය හෝ උඩැක්කිය සමඟ කළගෙඩි පිඹීමේ හඬ", "විදුලි ගිටාරය පමණි", "සැක්සෆෝනය", "බටහිර ඩ්‍රම් සෙට් එක", "සාම්ප්‍රදායික බෙර නාදය හා කළයෙන් නැඟෙන නාදය ගැමි රසය රකියි."),
        q("සබරගමු නැටුම් ක්ෂේත්‍රයේ 'ගුරු බැති පූජාව' හා 'පහන් දැල්වීම' සිදු කරන්නේ කුමන අරමුණින්ද?", "සමන් දෙවියන් හා පැරණි ආචාර්යවරුන් සිහි කර ආශිර්වාද ගැනීමට", "මඩු භූමිය උණුසුම් කර ආලෝකය ලබා ගැනීමට", "නැටුම් ඇඳුම් වියළා පිරිසිදු කර ගැනීමට", "ශාන්තිකර්මය අවසානයේ පඬුරු බෙදා ගැනීමට", "පාරම්පරික ශිල්පීය විනය රැකීම සබරගමු කලාවේ මුඛ්‍ය ලක්ෂණයකි."),
        q("ශ්‍රී ලංකාවේ සම්භාව්‍ය නර්තන සම්ප්‍රදායන් තුනෙන් සබරගමු නර්තනය වඩාත් සමීප වන්නේ කුමන චලන ලක්ෂණයකටද?", "උඩරට හා පහතරට සම්ප්‍රදායන් අතරමැදි ලැසි වක්‍ර චලන රටාවට", "සම්පූර්ණ බටහිර බැලේ චලනවලට", "කිසිදු අත් චලනයක් නැති ක්‍රමයට", "වෙස්මුහුණු නාට්‍ය පමණක් වන ක්‍රමයට", "භූගෝලීය පිහිටීම මෙන්ම ශෛලිමය ලක්ෂණ අතින්ද සබරගමුව මධ්‍යම ලාලිත්‍යයක් දරයි."),
        q("සබරගමු නර්තන ක්ෂේත්‍රයේ 'ගුරු ගෙදර' ක්‍රමයෙන් සිදු වූ ප්‍රධානතම මෙහෙය කුමක්ද?", "සම්ප්‍රදායික නැටුම් පද, කවි හා ශාන්තිකර්ම චාරිත්‍ර පරපුරෙන් පරපුරට රැකදීම", "පැරණි නැටුම් පොත්පත් සඟවා රහසිගතව තබා ගැනීම", "සාම්ප්‍රදායික දවුල් වාදනය සම්පූර්ණයෙන් නතර කිරීම", "දේශීය සරඹ වෙනුවට විදේශීය නැටුම් පමණක් ඉගැන්වීම", "ගුරුකුල ක්‍රමය දේශීය නර්තන අනන්‍යතාව ආරක්ෂා කිරීමේ මූලික පදනම විය."),
        q("සබරගමු නැටුමේදී ශිල්පියා පළඳින 'කොණ්ඩා මාලය' හෙවත් හිස් වැසුම් පළඳනාවේ අරමුණ කුමක්ද?", "සුදු ජටාව මත රිදී හෝ පිත්තල සැරසිලි රඳවා ගෞරවනීය පෙනුමක් දීම", "නැට්ටුවාගේ හිස බර කර චලන වේගය අඩු කිරීම පමණි", "සන්නි මුහුණක් මෙන් මුහුණ සම්පූර්ණයෙන් ආවරණය කිරීම", "දිගු දවුල හිස මත තබා ගැනීමට ආධාරකයක් සැපයීම", "සබරගමු ශිල්පියාගේ හිස් සැරසිල්ල ඔහුගේ සම්ප්‍රදායික තත්ත්වය පෙන්වයි."),
        q("ගැමි ජන නැටුමක් වන 'වී නෙළීමේ නැටුම' ඉදිරිපත් කරන විට නැට්ටුවන්ගේ මුහුණේ දිස්විය යුතු භාවය කුමක්ද?", "සතුටුදායක, උද්‍යෝගිමත් හා සුහදශීලී භාවය", "රෞද්‍ර කෝපය", "භයානක බියගැන්වීම", "තදබල ශෝකය", "සරු අස්වැන්නක් ලැබෙන විට ගැමි ජනතාව තුළ ඇතිවන ප්‍රීතිය ඉන් ප්‍රකාශ කෙරේ."),
        q("සබරගමු 'පහන් මඩුවක' දී නවකයන් නොවන ප්‍රවීණ ශිල්පීන් ඉදිරිපත් කරන 'අස්න කවි' වල අන්තර්ගතය කුමක්ද?", "දෙවිවරුන්ගේ උපත, පින් මහිමය සහ ඓතිහාසික පුරාවෘත්ත", "පැරණි කෝලම් හා සොකරි විකට දෙබස් කොටස්", "බටහිර සංගීත ස්වර ප්‍රස්තාර හා රිද්ම සටහන්", "රාජ සභා නඩු තීන්දු හා දඬුවම් නියමයන්", "සමන්, පත්තිනි හා විජය-කුවේණි පුවත් සබරගමු අස්න කවිවලින් ගැයේ."),
        q("ජන නැටුම් අතර 'පන්දම් නැටුමේදී' භාවිත කරන පන්දම් දැල්ල නොනිවී පවත්වා ගැනීමට ගන්නා ද්‍රව්‍යය කුමක්ද?", "පොල් තෙල් පෙඟවූ කපු රෙදි පටි සහ දුම්මල", "වතුර පෙඟවූ කඩදාසි", "වියළි කොළ රොඩු", "ලී කුඩු පමණි", "සුළඟේ පවා දැල්වෙන සේ සකස් කළ පන්දම් යොදා රංගනය ඉදිරිපත් කෙරේ."),
        q("සබරගමු සම්ප්‍රදායේ 'නැටුම් කවි' ගායනා කිරීමේදී යොදාගන්නා වෘත්ත හා තාල ලක්ෂණය කුමක්ද?", "දිගැති සිව්පද ආකෘතිය සහ මෘදු නාද ලාලිත්‍යය", "තනි වචනයේ කෙටි සටන් පාඨ", "වේගවත් රැප් ගායනා", "සංගීතය නැති කියවීම්", "සබරගමු කවි ගායන ශෛලිය ශ්‍රාවකයා තුළ භක්තිය හා සංවේදී බව ඇති කරයි."),
        q("කළගෙඩි නැටුමේදී ශිල්පිනියන් කළගෙඩිය තුළට 'පිඹීම' මගින් උපදවන්නේ කුමන ආකාරයේ නාදයක්ද?", "සෞම්‍ය, ගැඹුරු බටනලා හඬකට සමාන නාදයකි", "තියුණු ලෝහ ඝණ්ටාර හඬකි", "බෙර පැළෙන හඬකි", "කිසිදු හඬක් නොලැබේ", "කළගෙඩි කටට මුව තබා පිඹීමෙන් අලංකාර පසුබිම් නාදයක් නිර්මාණය වේ."),
        q("ලී කෙළි නැටුමේදී කණ්ඩායම වෘත්තාකාරව සිට ගමන් කරමින් ලී කෝටු ගැසීමේදී පවත්වා ගත යුත්තේ කුමක්ද?", "දකුණු හා වම් පාද පියවර සමඟ ලී කෝටු පහරවල් එකට සමපාත වීම", "කෝටු බිම අතහැර දිවීම", "වේගය අඩු වැඩි කර අවුල් කිරීම", "පිටුපසින් යන අය නතර කිරීම", "කණ්ඩායම් රිද්මය රැකීම ලී කෙළි නැටුමේ සාර්ථකත්වයට මූලික වේ."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ 'වට්ටම් පද' වාදනය කිරීමේදී දිගු දවුලට අමතරව රිද්මය රකින භාණ්ඩය කුමක්ද?", "තාලම්පට", "බටනලාව", "සිතාරය", "වයලීනය", "සියලු සබරගමු නැටුම්වල තාලයේ සමබරතාව රකින්නේ තාලම්පට විසිනි."),
        q("සිංහල ගැමි නැටුම් අතර 'පෙරහැර නැටුම්' ලෙස වැඩිපුරම එක් වන ජන නැටුම් මොනවාද?", "ලී කෙළි, පන්තේරු, රබන් සහ සවරම් නැටුම්", "මහ සොහොන් සමයම", "බලි ඇඹීම", "දහඅට සන්නි දෙබස්", "පෙරහැර ගමන් මාර්ගයේ ඇවිදිමින් ඉදිරිපත් කිරීමට මෙම ජන නැටුම් පහසු වේ."),
        q("සබරගමු නැටුමේදී ශිල්පියා තම ඇඳුමේ 'පොටවල්' සහ ඉණ පටිය තදින් බඳින්නේ ඇයි?", "වේගවත් කැරකිලිවලදී ඇඳුම ලිහිල් නොවී අලංකාර හැඩය රැකගැනීමට", "හුස්ම ගැනීම පාලනය කර ගැයීම අපහසු කිරීම සඳහා", "පාද චලන හා මණ්ඩි නැවීමේ වේගය අඩු කිරීම සඳහා", "සැරසිලි රෙදි පොටවල් වේදිකාවේ බිම ඇදගෙන යාමට", "දිගු වේලාවක් නැටීමේදී ඇඳුම ස්ථාවරව තිබීම ශිල්පියාට පහසුවකි."),
        q("සබරගමු 'පහන් මඩුව' ශාන්තිකර්මයේදී ගමේ ජනතාව එක්ව සූදානම් කරන 'දානමය කටයුත්ත' කුමක්ද?", "මුරුතැන් පූජාව සහ දේව දානය", "නාඩගම් රංගන තරගය", "ලී කෙළි ජන ක්‍රීඩා උළෙල", "සිංහල අවුරුදු රබන් තරගය", "ගැමි සමගිය හා පින් පැමිණවීම මෙම දේව දානය තුළින් ඉටු වේ."),
        q("ජන නැටුමක් වන 'ගොයම් නැටුමේදී' නැට්ටුවන් කණ්ඩායම පේළි දෙකකට සිට ඉදිරිපත් කරන රටාවෙන් පෙන්වන්නේ කුමක්ද?", "වෙල් යායේ නියර දිගේ ගමන් කරමින් එකට වැඩ කරන අයුරු", "කෝලම් හේවායන්ගේ යුද පෙළපාලි ගමන් විලාසය", "දේවාල ඇසළ පෙරහැරේ අලි ඇතුන්ගේ ගමන් රටාව", "පහතරට සන්නි යකුන් මඩුවට පිවිසෙන ගමන් රටාව", "ගැමි කාන්තාවන්ගේ අත්තම ක්‍රමයට ගොයම් කැපීම මෙම රංගනයට මුල් වී ඇත."),
        q("සබරගමු නර්තන කලාවේ 'අංග ලක්ෂණ' හා 'උඩරට අංග ලක්ෂණ' අතර වෙනස පෙන්වන ශරීර කොටස කුමක්ද?", "උඩුකය පැද්දීම සහ උරහිස් නම්‍යශීලීව චලනය වන ආකාරය", "නර්තනයේදී පාදවල ඇඟිලි තැබීමේ විශේෂ කෝණ ප්‍රමාණය", "වෙස් තට්ටුව පැළඳීමට පෙර හිසකෙස් බැඳ තබන ආකාරය", "හස්ත මුද්‍රා පෙන්වීමේදී අත්ල හා ඇඟිලි පිහිටන උස", "සබරගමු උඩුකය චලනයේ මෘදු වක්‍ර බව සුවිශේෂී හඳුනාගැනීමේ ලකුණකි."),
        q("සබරගමු නැටුමේදී ශිල්පියා 'මට්ටි සරඹ' අභ්‍යාසය නිම කරන විට අවසාන පියවර තබන්නේ කෙසේද?", "තාලයේ සම තිතට අනුව ස්ථාවර මණ්ඩි ඉරියව්වට පැමිණෙමින්", "වේදිකාවෙන් පැන යමින්", "බිම දිගා වෙමින්", "දවුල අතට ගනිමින්", "සෑම සරඹයක්ම තාලයේ මුල් තිතට නිවැරදිව අවසන් කිරීම නියමයකි."),
        q("ජන නැටුමක් වන 'අත් රබන්' නැටුමේදී නැට්ටුවන් විසින් රබාන උඩ දමා නැවත අල්ලා ගන්නා අවස්ථාවට හේතුව කුමක්ද?", "නැටුමට විචිත්‍ර හරඹ අලංකාරයක් හා කුතුහලයක් එක් කිරීම", "රබාන කැඩීමට උත්සාහ කිරීම", "තාලය අමතක වීම", "වේදිකාවෙන් ඉවත් කිරීම", "ශිල්පීය හස්ත කෞශල්‍යය ප්‍රේක්ෂකයන්ට පෙන්වීම මෙයින් සිදු කෙරේ."),
        q("සබරගමු සම්ප්‍රදායේ 'වන්නම්' අධ්‍යයනයේදී හමුවන 'හංස වන්නම' හෝ 'මයුර වන්නම' මගින් අනුකරණය කරන්නේ මොනවාද?", "හංසයාගේ හෝ මොනරාගේ ලැසි ගමන් හා ස්වාභාවික චලන", "රාජ සභා පුවත් හා නඩු තීන්දු විස්තර", "කමත් වැඩපොළේ වී පෑගීමේ ශ්‍රම ක්‍රියාව", "මඩු ශාන්තිකර්මයක පහන් පැල ඉදිකිරීමේ පිළිවෙත", "සත්ව චලන සෞම්‍ය ලෙස අනුකරණය කිරීම සබරගමු වන්නම්වලද දැකිය හැකිය."),
        q("ජන නැටුම් අතර 'වැදි නැටුම' ඉදිරිපත් කිරීමේදී නැට්ටුවන් භාවිත කරන ප්‍රධාන රංග උපකරණ මොනවාද?", "දුන්න, ඊතල සහ කොළ අතු සැරසිලි", "පිත්තල තාලම්පට සහ සළු", "මැටි කළගෙඩි", "ලෝහ කඩු", "ආදිවාසී සංස්කෘතිය හා දඩයම් ජීවන රටාව මෙම ජන නැටුමෙන් නිරූපණය වේ."),
        q("සබරගමු නර්තන ක්ෂේත්‍රයේදී 'පහන් මඩුව' පැවැත්වීමේදී භාවිත වන 'කප් සිටුවීම' සිදු කරන්නේ කවුරුන් සිහිපත් කරමින්ද?", "දෙවියන්ට භාර වීම හා මඩුවේ ආරක්ෂාව පැතීම සඳහා", "ජන ක්‍රීඩා උළෙලක ජයග්‍රහණ සැමරීමට", "සාම්ප්‍රදායික කෝලම් රංගනය අවසන් කිරීමට", "පැරණි බෙර වරපටි අලුතින් බැඳ තැබීමට", "මඩු ශාන්තිකර්මයක පූර්ව චාරිත්‍ර අතර කප් සිටුවීම අනිවාර්ය වේ."),
        q("සිංහල ජන නැටුම්වල 'සමූහ හැඩතල' වෙනස් කිරීමේදී 'තාල පාලම' ලෙස යොදාගන්නේ කුමක්ද?", "සරල ගමන් පදයක් හෝ බෙර වට්ටමක්", "දීර්ඝ නිහඬතාවක්", "ප්‍රේක්ෂක කතාවක්", "විදුලි පහන් නිවීමක්", "එක් රටාවකින් තවත් රටාවකට සුමටව මාරු වීමට ගමන් පද යොදාගනී."),
        q("සබරගමු නැටුමේදී ශිල්පියා පළඳින 'කයිමෙත්ත' හෝ 'අත් සැරසිලි' සාදා ඇත්තේ කුමන ද්‍රව්‍යවලින්ද?", "රෙදි, රේන්ද සහ පබළු වර්ගවලින්", "යකඩ තහඩුවලින්", "ගල් කැබලිවලින්", "රබර් පටිවලින්", "සබරගමු ඇඳුමේ වර්ණවත් බව රෙදි හා පබළු කැටයමින් වැඩි වේ."),
        q("සබරගමු නර්තන සම්ප්‍රදාය හා බැඳුණු 'රත්නපුර සමන් දේවාල පෙරහැරේ' නැට්ටුවන්ගේ ප්‍රධාන වගකීම කුමක්ද?", "පූජනීය පෙරහැර අංගයන්ට ඉදිරියෙන් සාම්ප්‍රදායික ගෞරව නැටුම් පැවැත්වීම", "පෙරහැර ගමන නතර කර දෙපස රැඳී සිටීම", "පෙරහැර මාර්ගයේදී විදේශීය ගීත වැයීම", "පූජා භූමියේ පාවහන් පැළඳ ගමන් කිරීම", "පූජනීය ධාතු හා දේවාභරණ වැඩමවීමේදී ශබ්ද හා නර්තන පූජා පවත්වයි."),
        q("ජන නැටුමක් වන 'කුළු නැටුමේදී' වී පෙළීමෙන් පසු සහල් වෙන් කර ගැනීමේ අභිනය දක්වන්නේ කෙසේද?", "කුල්ල ඇල කර ගැරීමේ හා වී ඉහළ දැමීමේ චලනවලින්", "කුල්ල බිම දමා පෑගීමෙන්", "කුල්ල හිසේ පැළඳීමෙන්", "අත් දෙක බැඳ සිටීමෙන්", "සැබෑ ගැමි කාර්යයේ සියුම් ඉරියව් නැටුමට අපූරුවට ගෙන ඇත."),
        q("සබරගමු නැටුමේදී 'වම් පය' සහ 'දකුණු පය' මාරු කරමින් නටන පියවරවලදී දණහිස් තබා ගත යුත්තේ කෙසේද?", "දෙපසට විහිදා මඳක් නැවී නම්‍යශීලීව", "සම්පූර්ණයෙන් කෙළින් ගල් කරගෙන", "ඇතුළට එකට වදින සේ", "බිම ගෑවෙන සේ", "සබරගමු මණ්ඩි නැවීම චලනවල සුමට බව රකියි."),
        q("සබරගමු 'පහන් මඩුව' තුළ ඉදිරිපත් කරන 'මල් යහන්' නැටුමේ අරමුණ කුමක්ද?", "පුද පූජා සඳහා සැරසූ මල් යහන් වෙත දෙවියන්ගේ බැල්ම ආරාධනා කිරීම", "පහන් මඩුවේ සැරසිලි මල් එකතු කර ඉවත් කිරීම", "මඩු යාගය අවසානයේ පූජා ආසනය ගලවා දැමීම", "ආරම්භයේදී දැල්වූ පොල් තෙල් පහන් නිවා දැමීම", "භක්තිමත් කවි හා දවුල් නාද මැද මල් යහන් නැටුම සිදු කෙරේ."),
        q("ගැමි ජන නැටුමක් වන 'මල් නැටුම' සඳහා ශිල්පිනියන් අතේ ගෙන යන්නේ මොනවාද?", "නැවුම් මල් පිරවූ කුඩා වට්ටි හෝ මල් කළඹ", "ලී කෙළි නැටුමට ගන්නා සවිමත් ලී කෝටු යුගල", "දිය පිරවූ සැහැල්ලු පිළිස්සූ මැටි කළගෙඩි", "තාල අල්ලන සිනිඳු පොල් කටු පළු යුගලය", "පූජා අරමුණු හා සෞන්දර්ය අලංකාරය මල් නැටුමෙන් මතු වේ."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ පැරණි ශිල්පීන් අතර 'කවි මතක තබා ගැනීමේ' හැකියාව වැදගත් වූයේ ඇයි?", "පහන් මඩුවක එළිවෙන තුරු ගායනා කිරීමට සිය ගණනක් කවි අවශ්‍ය වූ බැවින්", "පැරණි කවි පොත්පත් භාවිතයෙන් ඉවත් කිරීම සඳහා", "කවි ලිවීමට හා කියවීමට නොදැන සිටි බැවින් පමණි", "නර්තන තරග විනිශ්චය මණ්ඩල සඳහා ලකුණු දීමට", "මුඛ පරම්පරාගතව කවි හා පද රැකගෙන පැමිණීම ගුරුවරුන්ගේ විශේෂත්වයකි."),
        q("ජන නැටුමක් වන 'තෙල්මේ' නොවන 'දහඅට පාලිය' අයත් වන්නේ කුමන ප්‍රදේශයකටද?", "පහතරට සහ සබරගමු ශාන්තිකර්ම ප්‍රදේශවලට", "උතුරු ඉන්දියාවට", "යුරෝපීය බැලේ සම්ප්‍රදායට", "ජපන් නෝ නාට්‍යයට", "දේශීය ශාන්තිකර්ම පෙළපාලිවල පාලි අංග ඉතා ජනප්‍රිය වේ."),
        q("සබරගමු නැටුමේදී 'තීර්මාන' පදය වැයීමට පෙර දවුල් වාදකයා කරන්නේ කුමක්ද?", "පදයේ වේගය හා රටාව ක්‍රමයෙන් තීව්‍ර කර අවසාන තිතට ගෙන ඒම", "දිගු දවුල බිම තබා අත්පුඩි ගසමින් තාල ඇල්ලීම", "වාදනය මඳකට නවතා වේදිකාවෙන් පිටතට ඉවත් වීම", "දකුණු අතේ කඩිප්පුව අතහැර වම් අතින් පමණක් ගැසීම", "වාදකයාගේ පූර්ව ඉඟිය අනුව නැට්ටුවා තීර්මානය නිමා කරයි."),
        q("ජන නැටුම් අතර 'පොල්කෙළි නැටුමේදී' නැට්ටුවන් හවුලේ පොල් කටු ගසන විට වැදගත් වන කුසලතාව කුමක්ද?", "සහකරුගේ අතට හානියක් නොවන සේ නිවැරදි තාලයට පොල් කටු ගැසීම", "හැකිතාක් තදින් ගසා පොල් කටු දෙකට කැඩී යාම", "සහකරු දෙස නොබලා දෑස් පියාගෙන පොල් කටු ගැසීම", "කිසිදු පාද චලනයක් නොකර එකම තැන සිටගෙන සිටීම", "වේගවත් හුවමාරුවලදී අවධානය හා මිත්‍රශීලී සම්බන්ධීකරණය අත්‍යවශ්‍ය වේ."),
        q("සබරගමු සම්ප්‍රදායේ 'වන්නම්' හා 'උඩරට වන්නම්' අතර ප්‍රධාන සංගීතමය වෙනස කුමක්ද?", "භාවිත වන ප්‍රධාන බෙරය සහ කවි ගායනා කරන තාල ස්වරය", "එකක සංගීතයක් නොතිබීම", "විදේශීය භාෂාවෙන් ගැයීම", "බටහිර පියානෝ භාවිතය", "සබරගමුව දිගු දවුල හා ආවේණික ස්වර රටා භාවිත කරයි."),
        q("ජන නැටුම් ඉදිරිපත් කිරීමේදී 'ඇඳුම් පැළඳුම්' තෝරා ගැනීමේ මූලික රීතිය කුමක්ද?", "නැටුමේ තේමාවට, ගැමි සංස්කෘතියට හා චලන පහසුවට ගැළපෙන සේ තෝරා ගැනීම", "හැකිතාක් බර සහ දිග ඇඳුම් ඇඳීම", "නැටුමට නොගැළපෙන නවීන විලාසිතා ඇඳීම", "වර්ණ ගැන නොසැලකීම", "සැහැල්ලු හා සාම්ප්‍රදායික ඇඳුම් ජන නැටුමේ සජීවී බව වැඩි කරයි."),
        q("සබරගමු නැටුමේ 'පායිම්පත් මංගල්‍යය' පැවැත්වීමේදී ගුරුවරයා ඉටු කරන කාර්යය කුමක්ද?", "ශිෂ්‍යයාගේ හිසේ පායිම්පත බැඳ ආශිර්වාද කර කලා පරපුරට පිළිගැනීම", "ශිෂ්‍යයාට බෙරයක් තෑගි කර ඉවත් කිරීම", "ප්‍රේක්ෂකයන්ට පොත් බෙදීම", "වේදිකාව සේදීම", "පූර්ණ පුහුණුව සම්පූර්ණ වූ බවට නිල වශයෙන් පිළිගැනීම මින් සිදු වේ."),
        q("ගැමි ජන නැටුම් සඳහා ගැයෙන 'බඹර කවි' හෝ 'පැල් කවි' වලින් නිරූපණය කළ හැකි නව නැටුමක මූලික භාවය කුමක්ද?", "පරිසරයට ඇති ආදරය, වෙහෙස නිවා ගැනීම හා සොබාදහමේ අසිරිය", "රෞද්‍ර යුද සටන", "රජ සභා උත්සවය", "විද්‍යාගාර පරීක්ෂණය", "ශ්‍රී ලාංකේය ජන කවි නව ජන නැටුම් නිර්මාණයට පොහොසත් මූලාශ්‍ර සපයයි."),
        q("සබරගමු නැටුම් සම්ප්‍රදායේ 'මැටි පහන්' හා 'පොල් තෙල්' භාවිතය අනිවාර්ය වන්නේ කුමන අවස්ථාවේදීද?", "පහන් මඩු ශාන්තිකර්මයේදී", "ලී කෙළි තරගයේදී", "කළගෙඩි නැටුමේදී පමණි", "රබන් කරකැවීමේදී පමණි", "දෙවියන් උදෙසා පහන් පත්තු කර සෙත් පැතීම පහන් මඩුවේ ප්‍රධාන අංගයයි."),
        q("සබරගමු නැටුමේදී 'මණ්ඩිය' තබාගෙන වටේට කැරකෙන පියවර හඳුන්වන්නේ කුමන නමකින්ද?", "සබරගමු කරකැවිලි හෙවත් භ්‍රමණ පියවර", "කස්තිරම් අඩව්ව", "සන්නි පැනීම", "කෝලම් ගමන", "සමබරව සිරුර කරකැවීම සබරගමු නැටුමේ ලාලිත්‍යය ඉස්මතු කරයි."),
        q("ශ්‍රී ලාංකේය ජන නැටුම්වල 'බෙර හඬට' අමතරව රිද්මය මතු කරන වෙනත් ගැමි ශබ්ද මාධ්‍ය මොනවාද?", "තාලම්පට, අත්පුඩි, ලී කෝටු හා පොල් කටු ගැටෙන හඬ", "විදුලි ඕගන් හා කීබෝඩ් හඬ", "බටහිර පිත්තල නළා හා තූර්ය හඬ", "යාන්ත්‍රික සීනු හා ඝණ්ටාර හඬ", "ගැමි පරිසරයේ සුලබ උපකරණ තාල භාණ්ඩ බවට පත් කර ගැනීම ජන කලාවේ විශේෂත්වයකි."),
        q("සබරගමු නර්තන ක්ෂේත්‍රයේදී 'තාල ශාස්ත්‍රය' උගන්වන විට මූලිකවම හුරු කරවන තාල කොටස කුමක්ද?", "සබරගමු තුන්තිත හා සිව්තිත", "හින්දුස්ථානි ධමාර් තාලය", "බටහිර වෝල්ට්ස් තාලය", "ජපන් තාලය", "මූලික දේශීය තිත් ගණන් පදනම් කරගෙන සබරගමු පද නිර්මාණය වී ඇත."),
        q("ගැමි කාන්තාවන් විසින් 'රබන් නැටුම' ඉදිරිපත් කිරීමේදී රබාන එක් අතින් අනෙක් අතට මාරු කරන්නේ කෙසේද?", "තාලයට අනුව රබාන පිටුපසින් හෝ ඉහළින් මාරු කරමින්", "රබාන බිම විසි කරමින්", "නැටුම නවතා අතින් දෙමින්", "සගයන්ට පහර දෙමින්", "සෞම්‍ය මාරුවීම් රබන් නැටුමේ ප්‍රසංග ගුණය වැඩි කරයි."),
        q("සබරගමු නර්තන සම්ප්‍රදායේ 'මඩු පුරය' හෙවත් මඩු සැලැස්ම සකස් කරන්නේ කවුරුන් සඳහාද?", "ගමේ සියලු දෙනා එක්ව ශාන්තිකර්මය නැරඹීමට හා ආශිර්වාද ගැනීමට", "අසල්වැසි ගම්වල නරඹන්නන්ට බාධා කර දුරින් තැබීමට", "තනි පුද්ගලයෙකුට රහසේ සැඟවී යාතිකා සිදු කිරීමට", "ශාන්තිකර්මයේ ගොක් කොළ සැරසිලි ඉවත දමා තැබීමට", "පොදු සමාජ සුභසිද්ධිය වෙනුවෙන් ගම්මුන් එකමුතුව මඩුව ඉදිකරති."),
        q("ජන නැටුම් අතර 'පතල් කවි' සමඟ නටන නැටුමෙන් අවසානයේ පිළිබිඹු වන පණිවිඩය කුමක්ද?", "දුෂ්කර ශ්‍රමය මැද වුවද බලාපොරොත්තුව හා ජීවන අධිෂ්ඨානය පවත්වා ගැනීම", "දුෂ්කර පතල් කටයුතු අතහැර නගරයට පලා යාම සිදු කිරීම", "ගැමි මිතුරන් හා සහෝදර ශ්‍රමිකයන් සම්පූර්ණයෙන් අමතක කිරීම", "පතල් බිමේ ස්වාභාවික පරිසරය හා ගස්වැල් විනාශ කර දැමීම", "ශ්‍රමික ජනතාවගේ ධෛර්යය හා කලා රසිකත්වය ඉන් ඉස්මතු වේ."),
        q("සබරගමු නැටුමේ 'හිස සහ උරහිස්' චලනය වන විට නැට්ටුවාගේ මුහුණේ තිබිය යුතු ස්වභාවය කුමක්ද?", "ප්‍රසන්න, සෞම්‍ය හා අභිමානවත් සිනහමුසු ස්වභාවය", "කෝපයෙන් දත් මිටි කන ස්වභාවය", "බියෙන් වෙව්ලන ස්වභාවය", "නිදිමත ස්වභාවය", "සෞම්‍ය රංග විලාසය සබරගමු නැටුමට අත්‍යවශ්‍ය වේ."),
        q("සබරගමු නර්තන ක්ෂේත්‍රයේ ප්‍රවීණ ගුරු පරම්පරා අද වන විට තම දැනුම බෙදා දෙන ප්‍රධාන මාධ්‍ය මොනවාද?", "සාම්ප්‍රදායික කලායතන, පාසල් සහ විශ්වවිද්‍යාල අධ්‍යාපනය", "රහසිගත කුටි තුළ පවත්වන තනි පුහුණු පමණි", "විදේශීය ක්‍රීඩා සමාජ හා ව්‍යායාම ශාලා", "පුවත්පත් කෙටි දැන්වීම් හා ලිපි පුවරු", "විධිමත් අධ්‍යාපන පද්ධතිය නිසා සබරගමු නැටුම රට පුරා ව්‍යාප්ත වී ඇත."),
        q("ජන නැටුමක් වන 'ලී කෙළි' හා 'පන්තේරු' යන නැටුම් දෙකෙහි ප්‍රධාන වෙනස කුමක්ද?", "ලී කෙළි ලී කෝටු ගැසීමෙන්ද පන්තේරු පිත්තල වළල්ල කරකැවීමෙන්ද නැටීම", "ලී කෙළි මුවින් පිඹින සුසිර නැටුමක් ලෙස ඉදිරිපත් කිරීම", "පන්තේරු උපකරණය ජල බඳුනක තබා නැටීම සිදු කර පෙන්වීම", "ලී කෙළි හා පන්තේරු යන නැටුම් දෙකෙහි කිසිදු ශිල්පීය වෙනසක් නොමැත", "භාවිත කරන උපකරණය අනුව නැටුමේ ශිල්පීය චලන වෙනස් වේ."),
        q("සබරගමු 'පහන් මඩුවකදී' ආතුරයන්ට හා ගම්වාසීන්ට සෙත් පතා බෙදා දෙන පූජා වස්තුව කුමක්ද?", "දේව ආශිර්වාද ලත් පඬුරු, පිරිත් නූල් සහ මල්", "පැරණි බෙර කැබලි", "රබන් ලෑලි", "ලී කෙළි කෝටු", "යාගය අවසානයේ පූජනීය ආශිර්වාදය ජනතාව වෙත පිරිනමනු ලැබේ."),
        q("සබරගමු නර්තන සම්ප්‍රදායේදී 'තම්මැට්ටම්' හා 'හොරණෑ' වාදනය එක් වන විශේෂිත පූජා අවස්ථාව කුමක්ද?", "දේවාල තේවා සහ හේවිසි පූජා අවස්ථා", "රබන් කැරකැවීමේ තරග", "බැලේ ප්‍රසංග", "සන්නි දෙබස් අවස්ථා", "සාම්ප්‍රදායික දේවාල වන්දනාවන්හි හේවිසි පූජාව අනිවාර්ය අංගයකි."),
        q("සිංහල ජන නැටුම්වල 'සාමූහික රටා' අතර 'දියසුළි' හෙවත් සර්පිලාකාර රටාව මගින් ඇති කරන දෘශ්‍ය අලංකාරය කුමක්ද?", "වේදිකාව පුරා ගලා යන රිද්මයානුකූල චලන ප්‍රවාහයක් මැවීම", "සියලු නැට්ටුවන් එකම තැන ගල් ගැසී නිසොල්මන් වීම", "වේගවත් රිද්මය මැද නැටුම අතරමග සම්පූර්ණයෙන් නැවැත්වීම", "ප්‍රධාන පෙළ බිඳ දමා සියල්ලන් වේදිකාවෙන් බැස යාම", "රවුම් හා සර්පිල රටා ජන නැටුම්වල ගතික බව වැඩි කරයි."),
        q("සබරගමු නැටුම් සම්ප්‍රදායේ ආරක්ෂාව සඳහා 'රත්නපුර' ප්‍රදේශයේ පිහිටි ඓතිහාසික මූලස්ථානය කුමක්ද?", "මහ සමන් දේවාලය සහ පාරම්පරික කලායතන", "කොළඹ වරාය", "යාපනය කොටුව", "ගාල්ල කොටුව", "මහ සමන් දේවාලය හා බැඳුණු පූජා චාරිත්‍ර මෙම සම්ප්‍රදායේ ජීවනාලියයි."),
        q("සබරගමු නර්තන සම්ප්‍රදාය හා ජන නැටුම් අධ්‍යයනයෙන් O/L සිසුවෙකුට ලැබෙන ප්‍රධානම සංස්කෘතික අගය කුමක්ද?", "ලාංකේය ප්‍රාදේශීය නර්තන විවිධත්වය හඳුනාගෙන ජාතික උරුමය අගය කිරීම", "බටහිර ජෑස් හා ටැප් නැටුම් පමණක් ප්‍රගුණ කිරීම", "සියලු ශාස්ත්‍රීය බෙර පද ලිඛිත සටහන් අතහැර දැමීම", "එක් ප්‍රාදේශීය සම්ප්‍රදායක් පමණක් අගය කර සෙසු කලා ඉවතලීම", "උඩරට, පහතරට හා සබරගමු යන ත්‍රිවිධ සම්ප්‍රදායන්ගේම වටිනාකම අගය කිරීම වැදගත් වේ.")
    )
}
